from browser_validation import *
# Begin from the actual Reset control, then retain a static field for visual comparisons.
click('Reset all settings');click('Pause simulation');click('Render','tab');click('Performance');run('uncheck','#adaptive');run('uncheck','#taa');click('Orbit camera');run('set','viewport',390,844);snap();a=state();shot('mobile-initial-390x844.png')
check('390 by 844 responsive layout',ev('innerWidth===390 && innerHeight===844 && document.documentElement.scrollWidth===390') and a['p']['nonzero']>1000,{'size':a['d']['internalSize'],'page':ev('({width:innerWidth,height:innerHeight,scroll:document.documentElement.scrollWidth})'),'pixels':a['p']})
click('Open scene parameters');snap();shot('mobile-parameters.png');check('mobile parameter drawer',ev('document.getElementById("sidebar").classList.contains("open")'),True)
click('Environment','tab');range_to('mass',1.4);changed=state();check('mobile slider pointer input',abs(changed['d']['settings']['mass']-1.4)<.06,changed['d']['settings']['mass']);run('focus','#mass');run('press','ArrowRight');check('mobile slider keyboard continuity',ev('Horizon.diagnostics.settings.mass')>changed['d']['settings']['mass'],ev('Horizon.diagnostics.settings.mass'))
click('Camera','tab');click('Zoom in');check('mobile camera tab control',ev('Horizon.diagnostics.camera.distance')<22,ev('Horizon.diagnostics.camera.distance'));click('Close scene parameters');snap();shot('mobile-adjusted.png')
# The supplemental CDP input sends real multi-touch to the same agent-browser tab.
p=subprocess.run(['node',str(ROOT/'cdp_input.mjs'),'touch'],capture_output=True,text=True,env=os.environ,timeout=40);(ROOT/'logs'/'mobile-touch.json').write_text(p.stdout);assert p.returncode==0,p.stderr;touch=json.loads(p.stdout);check('mobile touch orbit pan and pinch',touch['before']['camera']['pitch']!=touch['after']['camera']['pitch'] and touch['before']['camera']['distance']!=touch['after']['camera']['distance'] and touch['before']['camera']['target']!=touch['after']['camera']['target'],touch);shot('mobile-touch-orbit-pinch.png')
click('Classic');run('wait','--fn','Math.abs(Horizon.diagnostics.camera.distance-22)<.01');p=subprocess.run(['node',str(ROOT/'cdp_input.mjs'),'tap'],capture_output=True,text=True,env=os.environ,timeout=40);(ROOT/'logs'/'mobile-tap.json').write_text(p.stdout);assert p.returncode==0,p.stderr;s=state();shot('mobile-ray-inspector.png');check('tap selects a ray with values',s['d']['selected'] is not None and s['d']['selectedRay']['steps']>0,s['d']['selectedRay']);click('Close ray inspector')
for mode in ['2','3','1']:
 run('select','#viewMode',mode);s=state();shot('mobile-diagnostic-'+mode+'.png');check('mobile diagnostic '+mode,s['d']['settings']['mode']==int(mode) and s['p']['glError']==0,s['p'])
run('select','#viewMode','0');click('Controls and help');snap();shot('mobile-help.png');click('Close controls and help')
click('Open scene parameters');click('Render','tab');run('scroll','down',650,'--selector','#panelScroll');shot('mobile-render-controls.png');check('narrow render controls reachable',ev('(()=>{let r=document.getElementById("exportBtn").getBoundingClientRect();return r.y>63&&r.bottom<816})()'),ev('document.getElementById("exportBtn").getBoundingClientRect().toJSON()'));click('Close scene parameters')
errors=run('errors');check('mobile runtime and console',not errors.get('errors') and not ev('Horizon.diagnostics.errors'),{'errors':errors.get('errors'),'console':run('console').get('messages')})
